-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann ein Einzelunternehmen mehrere Inhaber haben?', 2, '[{"text": "Nein", "correct": true, "because": "Nur ein Inhaber möglich"}, {"text": "Ja", "correct": false, "because": "Definition Einzelunternehmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Einzelunternehmen ins Handelsregister eingetragen werden?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei Gewerbe Gewerbeanmeldung"}, {"text": "Ja", "correct": false, "because": "Pflicht nur bei Handelsgewerbe"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Haftung beim Einzelunternehmen begrenzt?', 2, '[{"text": "Nein", "correct": true, "because": "Unbeschränkte Haftung"}, {"text": "Ja", "correct": false, "because": "Vollhaftung mit Privatvermögen"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ein Einzelunternehmen im Handwerk typisch sein?', 2, '[{"text": "Ja", "correct": true, "because": "Häufig im Handwerk"}, {"text": "Nein", "correct": false, "because": "Nicht branchenspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Ist die Gründung eines Einzelunternehmens teuer?', 2, '[{"text": "Nein", "correct": true, "because": "Geringe Startkosten"}, {"text": "Ja", "correct": false, "because": "Kein Mindestkapital nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Einzelunternehmen ohne Gewerbeanmeldung arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Gewerbeanmeldung Pflicht"}, {"text": "Ja", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Vorteil des Einzelunternehmens die einfache Entscheidungsfindung?', 2, '[{"text": "Ja", "correct": true, "because": "Ein Inhaber entscheidet"}, {"text": "Nein", "correct": false, "because": "Klarer Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Einzelunternehmen Steuern zahlen?', 2, '[{"text": "Ja", "correct": true, "because": "Steuerpflicht wie alle"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil eines Einzelunternehmens?', 2, '[{"text": "Schnelle Entscheidungen", "correct": true, "because": "Ein Inhaber"}, {"text": "Begrenzte Haftung", "correct": false, "because": "Nachteil"}, {"text": "Hohe Gründungskosten", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin überlegt ein Einzelunternehmen. Was ist ein Nachteil?', 3, '[{"text": "Unbeschränkte Haftung", "correct": true, "because": "Risiko mit Privatvermögen"}, {"text": "Einfache Gründung", "correct": false, "because": "Vorteil"}, {"text": "Wenig Bürokratie", "correct": false, "because": "Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Branche ist für ein Einzelunternehmen typisch?', 2, '[{"text": "Handwerk", "correct": true, "because": "Häufige Nutzung"}, {"text": "Nur Großindustrie", "correct": false, "because": "Zu spezifisch"}, {"text": "Nur IT", "correct": false, "because": "Nicht ausschließlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt nach der Haftung im Einzelunternehmen. Was sage ich?', 3, '[{"text": "Unbeschränkt mit Privatvermögen", "correct": true, "because": "Haftungsstruktur"}, {"text": "Nur Geschäftskapital", "correct": false, "because": "Falsch"}, {"text": "Keine Haftung", "correct": false, "because": "Unrealistisch"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Einzelunternehmen?', 4, '[{"text": "Einfache Gründung", "correct": true, "because": "Wenig Aufwand"}, {"text": "Alleingewinne", "correct": true, "because": "Kein Teilen"}, {"text": "Schnelle Entscheidungen", "correct": true, "because": "Ein Inhaber"}, {"text": "Begrenzte Haftung", "correct": false, "because": "Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sind Nachteile eines Einzelunternehmens?', 3, '[{"text": "Unbeschränkte Haftung", "correct": true, "because": "Risiko"}, {"text": "Alleiniges Risiko", "correct": true, "because": "Keine Partner"}, {"text": "Begrenzte Finanzierung", "correct": true, "because": "Eigenkapital"}, {"text": "Einfache Steuern", "correct": false, "because": "Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche rechtlichen Anforderungen gibt es für ein Einzelunternehmen?', 3, '[{"text": "Gewerbeanmeldung", "correct": true, "because": "Pflicht GewerbeG"}, {"text": "Steueranmeldung", "correct": true, "because": "Finanzamt"}, {"text": "Eintrag Handelsregister bei Handelsgewerbe", "correct": true, "because": "HGB"}, {"text": "Mindestkapital", "correct": false, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zum Gründungsprozess eines Einzelunternehmens?', 4, '[{"text": "Gewerbeanmeldung", "correct": true, "because": "Erster Schritt"}, {"text": "Finanzamt informieren", "correct": true, "because": "Steuerpflicht"}, {"text": "Bankkonto eröffnen", "correct": true, "because": "Geschäftsbetrieb"}, {"text": "Gesellschaftervertrag", "correct": false, "because": "Nicht nötig"}]'),
