('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Einzelunternehmen hat unbeschränkte Haftung. b) Es braucht mehrere Inhaber.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Haftung ja, Inhaber nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Gründung ist einfach. b) Es ist für Großindustrie typisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gründung ja, Großindustrie nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Einzelunternehmen hat schnelle Entscheidungen. b) Es erfordert Mindestkapital.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Entscheidungen ja, Kapital nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Gewerbeanmeldung ist Pflicht. b) Haftung ist begrenzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anmeldung ja, Haftung nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

